<script setup lang="ts">
/**
 * A command list behind a trigger (`design/components/menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, provide, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/menu'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentMember,
  anchorProps,
  chooseMenuEntry,
  followHighlight,
  menuChoices,
  syncTriggerAnchor,
  useDirection,
  useMediaQuery,
  type IconRole,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Kbd from '../structure/Kbd.vue'
import MenuSubmenu from './MenuSubmenu.vue'

export type MenuPresentation = NonNullable<MenuProps['presentation']>

export type MenuAlign = NonNullable<MenuProps['align']>

export interface MenuItemEntry {
  kind?: 'item'
  label: string
  icon?: IconRole
  kbd?: string
  tone?: 'neutral' | 'danger'
  disabled?: boolean
  onSelect: () => void
}

export interface MenuCheckboxEntry {
  kind: 'checkbox'
  label: string
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  disabled?: boolean
}

export interface MenuSeparatorEntry {
  kind: 'separator'
}

export interface MenuLabelEntry {
  kind: 'label'
  label: string
}

export type MenuLeafEntry = MenuItemEntry | MenuCheckboxEntry | MenuSeparatorEntry | MenuLabelEntry

export interface MenuSubmenuEntry {
  kind: 'submenu'
  label: string
  icon?: IconRole
  disabled?: boolean
  items: MenuLeafEntry[]
}

export type MenuEntry = MenuLeafEntry | MenuSubmenuEntry

export interface MenuProps {
  align?: 'start' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  items: MenuEntry[]
  /**
   * The controlled pair; uncontrolled is the default. Use it to keep the menu open across
   * several checkbox toggles, or to close it on "apply".
   */
  open?: boolean
  /**
   * `'auto'` uses a sheet below `30rem` (the sheet presentation, `design/components/README.md`),
   * the phone's standard pattern for "choose from these". `'popover'` keeps the popper at every
   * width, for the rare pointer-first embed that needs precision. There is no always-`'sheet'`
   * value, because a bottom sheet does not suit a wide pointer surface, and the closed union
   * rejects it (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
}

defineOptions({ name: 'Menu', inheritAttrs: false })

const props = withDefaults(defineProps<MenuProps>(), {
  align: 'start',
  defaultOpen: undefined,
  open: undefined,
  presentation: 'auto',
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{ trigger: (props: Record<string, never>) => unknown }>()
const uid = useId()
const anchor = useTemplateRef<HTMLElement>('anchor')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const flat = computed(() =>
  props.items.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    positioning: { placement: `bottom-${props.align}`, gutter: 2 },
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
    onSelect: (details) => {
      flat.value.forEach(
        (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
provide('polymorph:Menu', {
  get api() {
    return api.value
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
const effect2 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect2)
watch(() => api.value.highlightedValue, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Menu',
    element: () => anchor.value?.querySelector('button, a[href], [tabindex]'),
    state: () => ({ open: api.value.open, entries: menuChoices(props.items) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          chooseMenuEntry(props.items, value) && api.value.open && api.value.setOpen(false),
      },
      open: () => api.value.open || api.value.setOpen(true),
      close: () => api.value.open && api.value.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <span ref="anchor" v-bind="anchorProps(api.getTriggerProps())" :class="triggerAnchor.anchor">
    <slot name="trigger" />
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{
          '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
          '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
        }"
        :hidden="undefined"
        data-member="menu"
        @focus="followHighlight(panel, api.highlightedValue)"
      >
        <template v-for="(entry, index) in items" :key="index">
          <div
            v-if="entry.kind === 'separator'"
            v-bind="api.getSeparatorProps()"
            :class="styles.separator"
          />
          <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
            {{ entry.label }}
          </div>
          <div
            v-else-if="entry.kind === 'checkbox'"
            v-bind="
              api.getOptionItemProps({
                type: 'checkbox',
                value: entry.label,
                checked: entry.checked,
                disabled: entry.disabled,
                closeOnSelect: false,
                onCheckedChange: entry.onCheckedChange,
              })
            "
            :class="[styles.item, styles.checkbox]"
            data-menu-part="checkbox"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span :class="styles.check">
              <Icon v-if="entry.checked" name="confirm" size="sm" />
            </span>
            <span :class="styles.label">
              {{ entry.label }}
            </span>
          </div>
          <MenuSubmenu v-else-if="entry.kind === 'submenu'" :entry="entry" />
          <div
            v-else
            v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
            :class="styles.item"
            :data-tone="entry.tone ?? 'neutral'"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span v-if="entry.icon !== undefined" :class="styles.glyph">
              <Icon :name="entry.icon" size="sm" />
            </span>
            <span :class="styles.label">
              {{ entry.label }}
            </span>
            <span v-if="entry.kbd !== undefined" :class="styles.hint">
              <Kbd>
                {{ entry.kbd }}
              </Kbd>
            </span>
          </div>
        </template>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
        tabindex="-1"
      >
        <!-- panel -->
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.sheetList"
          :hidden="undefined"
          data-member="menu"
          @focus="followHighlight(panel, api.highlightedValue)"
        >
          <template v-for="(entry, index) in flat" :key="index">
            <div
              v-if="entry.kind === 'separator'"
              v-bind="api.getSeparatorProps()"
              :class="styles.separator"
            />
            <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
              {{ entry.label }}
            </div>
            <div
              v-else-if="entry.kind === 'checkbox'"
              v-bind="
                api.getOptionItemProps({
                  type: 'checkbox',
                  value: entry.label,
                  checked: entry.checked,
                  disabled: entry.disabled,
                  closeOnSelect: false,
                  onCheckedChange: entry.onCheckedChange,
                })
              "
              :class="[styles.item, styles.checkbox]"
              data-menu-part="checkbox"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span :class="styles.check">
                <Icon v-if="entry.checked" name="confirm" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
            </div>
            <div
              v-else
              v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
              :class="styles.item"
              :data-tone="entry.tone ?? 'neutral'"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span v-if="entry.icon !== undefined" :class="styles.glyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
              <span v-if="entry.kbd !== undefined" :class="styles.hint">
                <Kbd>
                  {{ entry.kbd }}
                </Kbd>
              </span>
            </div>
          </template>
        </div>
      </div>
    </div>
  </Teleport>
</template>
